function eval_cat_item() {
   var cat_item = "";
   var className = current.getRecordClassName();
   if (className == "sc_req_item") {
      cat_item = current.cat_item;
   } else if (className == "sc_task") {
      cat_item = current.request_item.cat_item;
   }
   return cat_item;
}
eval_cat_item();

       var jvar_cat_sets = "";
